<script setup lang="ts">
import { sampleDeliveries } from '~/data/management-scenarios'
import type { DeliverySnapshot } from '~/types/management'

definePageMeta({ layout: 'staff' }); useSeoMeta({ title: 'Notification delivery preview' })
const channel = ref(''); const status = ref(''); const selected = ref<DeliverySnapshot | null>(null); const review = ref(false); const notice = ref('')
const activeFilters = computed(() => [channel.value ? `Channel ${channel.value}` : '', status.value ? `Status ${status.value}` : ''].filter(Boolean))
const filtered = computed(() => sampleDeliveries.filter(item => (!channel.value || item.channel === channel.value) && (!status.value || item.status === status.value)))
function reset() { channel.value = ''; status.value = '' }
function retry() { if (!selected.value) return; notice.value = `Retry ${selected.value.id} disimulasikan. Pesan tidak dikirim dan status tetap ${selected.value.status}.`; review.value = false }
</script>
<template><div class="container ops-page"><StaffPageHeader eyebrow="Delivery operations" title="Notifications" description="Riwayat delivery, jumlah percobaan, dan recovery per channel." /><UiInlineAlert tone="info">Data sample dan penerima dimask. Backend delivery/retry belum tersedia.</UiInlineAlert><UiInlineAlert v-if="notice" tone="info" live>{{ notice }}</UiInlineAlert><StaffFilterBar :active="activeFilters" :result-label="`${filtered.length} delivery`" @reset="reset"><div class="field"><label for="delivery-channel">Channel</label><select id="delivery-channel" v-model="channel"><option value="">Semua</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option></select></div><div class="field"><label for="delivery-status">Status</label><select id="delivery-status" v-model="status"><option value="">Semua</option><option value="accepted">Accepted</option><option value="queued">Queued</option><option value="sent">Sent</option><option value="delivered">Delivered</option><option value="failed">Failed</option><option value="unknown">Unknown</option></select></div></StaffFilterBar><StaffDataState v-if="!filtered.length && activeFilters.length" no-results @reset="reset" /><div v-else class="ops-grid"><article v-for="item in filtered" :key="item.id" class="ops-card" :class="{ 'ops-card--selected': selected?.id === item.id }"><div class="ops-card__top"><div><p class="eyebrow">{{ item.channel }}</p><h3>{{ item.template }}</h3></div><StaffStatusBadge :label="item.status" :status="item.status" /></div><p>{{ item.recipient }} · {{ item.attempts }} percobaan</p><small>{{ new Date(item.updatedAt).toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' }) }}</small><BrandButton @click="selected = item">Lihat timeline</BrandButton></article></div><StaffDetailDrawer id="delivery-detail" :open="Boolean(selected) && !review" :title="selected?.template || 'Detail delivery'" eyebrow="Notification" @close="selected = null"><div v-if="selected" class="stack"><p><strong>Penerima</strong><br>{{ selected.recipient }}</p><p><strong>Reference</strong><br>{{ selected.reference }}</p><ol class="stack"><li v-for="event in selected.timeline" :key="`${event.status}-${event.at}`"><StaffStatusBadge :label="event.status" :status="event.status" /> {{ new Date(event.at).toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' }) }}</li></ol><BrandButton dark :disabled="!selected.retryEligible" @click="review = true">Tinjau retry sample</BrandButton></div></StaffDetailDrawer><StaffActionDialog id="delivery-retry" :open="review" title="Konfirmasi retry notification" @close="review = false"><p v-if="selected">{{ selected.channel }} ke {{ selected.recipient }} untuk template <strong>{{ selected.template }}</strong>.</p><UiInlineAlert tone="error">Provider mungkin sudah menerima pesan. Retry dapat menghasilkan delivery duplikat dan tidak berlaku untuk OTP lama.</UiInlineAlert><template #actions><BrandButton dark @click="retry">Simulasikan retry</BrandButton><BrandButton @click="review = false">Kembali</BrandButton></template></StaffActionDialog></div></template>
